local S=string
local B=S.byte
local C=S.char
local F=math.floor
local TC=table.concat
local function X(a,b)
 local r,p=0,1
 while a>0 or b>0 do
  local x=a%2
  local y=b%2
  if x~=y then r=r+p end
  a=F(a/2); b=F(b/2); p=p*2
 end
 return r
end
local function D(s)
 local A="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
 local M={} for i=1,#A do M[A:sub(i,i)]=i-1 end
 local O={} local N=0 local V=0 local Q=0
 for i=1,#s do
  local c=s:sub(i,i)
  if c~="=" then
   local v=M[c]
   if v then
    V=V*64+v; Q=Q+6
    while Q>=8 do
     Q=Q-8; N=N+1
     O[N]=C(F(V/(2^Q))%256)
     V=V%(2^Q)
    end
   end
  end
 end
 return TC(O)
end
